  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.box.value =
        this.plot.value === null ? this.box.value : measureBox(this.plot.value, this.box.value)
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.plot.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.reading.value.subscribe((now) => {
      this.position.value = now
    })
  }

  private effect3(): void {
    this.warningLog.value.log(this.model.value.warnings, (message) => devWarning(true, message))
  }

  private effect4(): void {
    this.cap.value =
      this.model.value.state === 'empty' ? this.cap.value : readChartCap(this.plot.value)
  }

  private effect5(): void {
    this.release5?.()
    const ran =
      !this.$.listening(this.onSelect, 'onSelect') && !this.model.value.legend
        ? () => {}
        : agentMember({
            member: 'RadarChart',
            element: () => this.frame.value,
            state: () => ({
              items: this.$.listening(this.onSelect, 'onSelect')
                ? chartMarks(this.marks.value, this.reading.value)
                : [],
              position: chartPosition(this.marks.value, this.reading.value),
              count: this.walk.value.count,
              series: chartSeries(this.frame.value, chartLegend.key, this.model.value.painted),
              hidden: chartHiddenSeries(
                this.frame.value,
                chartLegend.key,
                this.model.value.painted,
              ),
            }),
            actions: {
              read: {
                argument: 'number',
                run: (value) => readChartPosition(this.marks.value, value, this.reading.value),
              },
              choose: {
                argument: 'id',
                among: 'items',
                run: (value) =>
                  chooseChartMark(this.marks.value, value, this.reading.value, this.activate.value),
              },
              toggle: {
                argument: 'id',
                among: 'series',
                run: (value) =>
                  toggleChartSeries(
                    this.frame.value,
                    chartLegend.key,
                    this.model.value.painted,
                    value,
                  ),
              },
            },
          })
    this.release5 = () => {
      ran()
    }
  }
